package com.baystudio.droide.core

import java.io.File
import java.nio.file.Files
import java.nio.file.LinkOption.NOFOLLOW_LINKS
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.ensureActive
import kotlinx.serialization.json.*

/** Byte-only discovery and full protected proof. It never imports an original module or executes health. */
internal object LocalUbuntuVueLaunchAuthority {
    const val FILE_NAME="VUE_AUTHORITY.json"
    const val CLOSURE_FILE="VUE_CLOSURE.json"
    const val HEALTH_SEED="payload/vue-health-identity.json"
    const val POLICY=LspVueLaunchPolicy.PROFILE
    val helperPaths=listOf(LspVueLaunchPolicy.SUPERVISOR,LspVueLaunchPolicy.MULTIPLEXER,LspVueLaunchPolicy.HEALTH,LspVueLaunchPolicy.HELPER_HEALTH)
    val expectedHelperHashes:Map<String,String> = mapOf(
        "payload/vue-supervisor.cjs" to "75641233ffb1ddf8dbb57c0676b67701b0feee740a39575d5a25211a0ccca71b",
        "payload/vue-multiplexer.cjs" to "c76e7e98b2244efabe6242fbe4b601a1ff835b1f8f3e3410c28fceb363fa71ff",
        "payload/vue-native-health.cjs" to "52f4a7b904607edfc241e1e5fcda9ef4c18b6043f3b59a3501bcda94eae11ec4",
        "payload/vue-helper-identity-health.cjs" to "32e175d9f5acc7667770b2afa0c0fa23c359a5c8cc869dff2b5156f39dd7b9b4"
    )
    internal fun receiptSha(record:ManagedPackageRecord)=LocalUbuntuPowerShellLaunchAuthority.receiptSha(record)
    internal fun objectAt(file:File,limit:Int=65536,active:()->Unit={}):JsonObject=LocalUbuntuPowerShellRuntimePolicy.strictObject(NimRuntimeClosure.readText(file,limit,active),limit)
    private fun text(o:JsonObject,key:String)=LocalUbuntuPowerShellRuntimePolicy.string(o,key)
    private fun sha(file:File,max:Long=134217728,active:()->Unit={})=NimRuntimeClosure.measure(file,max,active).second
    private fun mapping(m:Map<String,String>)=JsonObject(m.toSortedMap().mapValues{JsonPrimitive(it.value)})
    private fun packageRoot(family:String)="/opt/droide/packages/$family/${LocalUbuntuVuePolicy.version(family)}/arm64-v8a"
    private fun requireRecord(record:ManagedPackageRecord,appRoot:String){require(LocalUbuntuVuePolicy.isFamily(record.familyId)&&record.version==LocalUbuntuVuePolicy.version(record.familyId));val kind=if(record.familyId==LocalUbuntuVuePolicy.FAMILY)LocalManagedPackageMetadata.KIND_UBUNTU_NPM else LocalManagedPackageMetadata.KIND_UBUNTU_VENDOR_TREE
        LocalPackageInstallJournal.requireNoVueHealthHold(LocalPackageInstallJournal.paths(appRoot,record.familyId,record.version,kind))
        require(record.installRoot==LocalPackageInstallJournal.paths(appRoot,record.familyId,record.version,kind).final.absolutePath&&record.abi=="arm64-v8a"&&record.scope==ExecutionScope.LOCAL_LINUX_ARM64.name)
        require(record.artifactSha256==if(record.familyId==LocalUbuntuVuePolicy.FAMILY)LocalUbuntuVuePolicy.DATA_SHA256 else LocalUbuntuVueHelperPolicy.SHA256)
        require(record.checksumFile=="SHA256SUMS"&&record.environment.isEmpty()&&record.metadata[LocalManagedPackageMetadata.KIND_KEY]==kind&&record.metadata[LocalManagedPackageMetadata.PROFILE_KEY]==DeclarativeGuestProfile.UBUNTU_24_04_GLIBC_ARM64.name&&record.metadata[LocalManagedPackageMetadata.LIBC_KEY]==DeclarativeLibcCompatibility.GLIBC.name)
        val command=if(record.familyId==LocalUbuntuVuePolicy.FAMILY)LocalUbuntuVuePolicy.COMMAND else LocalUbuntuVueHelperPolicy.COMMAND
        require(record.pathEntries==listOf("${record.installRoot}/payload/host-bin")&&record.commands==mapOf(command to "${record.installRoot}/payload/host-bin/$command")&&record.healthChecks==listOf(ManagedPackageHealthCheck("host-bin/$command",listOf("--health"))))
        val root=File(record.installRoot);require(NimRuntimeClosure.readText(File(root,"payload/bin/$command"),65536)==guestWrapper(record.familyId,packageRoot(record.familyId)))
        require(NimRuntimeClosure.readText(File(root,"payload/host-bin/$command"),65536)==LocalUbuntuVendorPolicy.hostWrapper("$appRoot/guest/${FoundryUbuntuGuestEnvironmentSpec.ROOT_DIR}/launch","${packageRoot(record.familyId)}/payload/bin/$command"))
        if(record.familyId==LocalUbuntuVueHelperPolicy.FAMILY){val recipe=requireNotNull(LocalUbuntuVendorPolicy.fromReceipt(record));LocalUbuntuVueHelperPolicy.requireReviewed(recipe);require(LocalUbuntuVendorPolicy.verifyIntegration(record,recipe,appRoot))}

    }
    private fun helpers(root:File,active:()->Unit={}){for((path,hash)in expectedHelperHashes){active();require(sha(File(root,path),1048576,active)==hash)}}
    fun stagedHelperAuthority(stage:File,finalGuest:String,activation:String,appRoot:String):Map<String,String>{
        require(finalGuest==LocalUbuntuVueHelperPolicy.ROOT&&activation.matches(Regex("[0-9a-f-]{36}")));require(stage.absolutePath==LocalPackageInstallJournal.paths(appRoot,LocalUbuntuVueHelperPolicy.FAMILY,LocalUbuntuVueHelperPolicy.VERSION,LocalManagedPackageMetadata.KIND_UBUNTU_VENDOR_TREE).stage.absolutePath);helpers(stage)
        val inv=LocalUbuntuVueHelperPolicy.requireTree(File(stage,"payload/tree/${LocalUbuntuVueHelperPolicy.ENTRY}"));val closure=NimRuntimeClosure.requireExecutionClosure(listOf(inv),File(appRoot,"guest/${FoundryUbuntuGuestEnvironmentSpec.ROOT_DIR}/rootfs"),emptySet())
        val config=LocalUbuntuVueHelperPolicy.requireConfiguration(File(stage,"payload/tree/${LocalUbuntuVueHelperPolicy.CONFIG}"));val c=buildJsonObject{put("schema",1);put("files",mapping(closure.files));put("sha256",closure.sha256)}.toString()+"\n"
        val a=buildJsonObject{put("schema",1);put("policy",POLICY);put("family",LocalUbuntuVueHelperPolicy.FAMILY);put("version",LocalUbuntuVueHelperPolicy.VERSION);put("stage",stage.absolutePath);put("final",finalGuest);put("activation",activation);put("archiveSha256",LocalUbuntuVueHelperPolicy.SHA256);put("configSha256",config);put("closureSha256",closure.sha256);put("sourceCommit",LocalUbuntuVueHelperPolicy.SOURCE_COMMIT);put("sourceBindingSha256",LocalUbuntuVueHelperPolicy.SOURCE_BINDING_SHA256);put("helpers",mapping(expectedHelperHashes));put("treeManifestSha256",sha(File(stage,"TREE_SHA256SUMS"),16777216));put("dependencyReceipts",JsonObject(emptyMap()))}.toString()+"\n"
        return mapOf(FILE_NAME to a,CLOSURE_FILE to c)
    }
    fun stagedAuthority(stage:File,finalGuest:String,activation:String,helper:ManagedPackageRecord,appRoot:String):Map<String,String>{
        require(finalGuest==LocalUbuntuVuePolicy.ROOT&&activation.matches(Regex("[0-9a-f-]{36}")));require(stage.absolutePath==LocalPackageInstallJournal.paths(appRoot,LocalUbuntuVuePolicy.FAMILY,LocalUbuntuVuePolicy.VERSION,LocalManagedPackageMetadata.KIND_UBUNTU_NPM).stage.absolutePath);requireRecord(helper,appRoot);require(helper.familyId==LocalUbuntuVueHelperPolicy.FAMILY);helpers(stage);LocalUbuntuVuePolicy.validateInstalledLayout(stage)
        val h=generation(helper,appRoot,{}).first;val closure=objectAt(File(helper.installRoot,CLOSURE_FILE));val c=closure.toString()+"\n"
        val a=buildJsonObject{put("schema",1);put("policy",POLICY);put("family",LocalUbuntuVuePolicy.FAMILY);put("version",LocalUbuntuVuePolicy.VERSION);put("stage",stage.absolutePath);put("final",finalGuest);put("activation",activation);put("archiveSha256",LocalUbuntuVuePolicy.DATA_SHA256);put("configSha256",text(h,"configSha256"));put("closureSha256",text(h,"closureSha256"));put("sourceCommit",LocalUbuntuVueHelperPolicy.SOURCE_COMMIT);put("sourceBindingSha256",LocalUbuntuVueHelperPolicy.SOURCE_BINDING_SHA256);put("helpers",mapping(expectedHelperHashes));put("dependencyReceipts",mapping(mapOf(helper.familyId to receiptSha(helper))))}.toString()+"\n"
        val entries=mapOf("serverExecutable" to LocalUbuntuVuePolicy.VUE_ENTRY,"typescriptLspExecutable" to LocalUbuntuVuePolicy.TSLSP_ENTRY,"typescriptServerExecutable" to LocalUbuntuVuePolicy.TS_ENTRY,"typescriptLibrary" to LocalUbuntuVuePolicy.TS_LIBRARY,"pluginExecutable" to LocalUbuntuVuePolicy.PLUGIN_ENTRY)
        val proofs=(helperPaths+entries.values).associate{stage.absolutePath+"/"+it to sha(File(stage,it))}.toMutableMap();proofs[LocalUbuntuVueHelperPolicy.EXECUTABLE]=sha(File(helper.installRoot,"payload/tree/${LocalUbuntuVueHelperPolicy.ENTRY}"));proofs["${stage.absolutePath}/$FILE_NAME"]=LspVueLaunchPolicy.sha(a.toByteArray());proofs["${stage.absolutePath}/$CLOSURE_FILE"]=LspVueLaunchPolicy.sha(c.toByteArray())
        val seed=buildJsonObject{put("packageRoot",stage.absolutePath);put("npmRoot","${stage.absolutePath}/payload/npm");for((key,relative)in entries)put(key,"${stage.absolutePath}/$relative");put("helperExecutable",LocalUbuntuVueHelperPolicy.EXECUTABLE);put("helperSourceCommit",LocalUbuntuVueHelperPolicy.SOURCE_COMMIT);put("helperArchiveSha256",LocalUbuntuVueHelperPolicy.SHA256);put("helperConfigSha256",text(h,"configSha256"));put("helperSourceBindingSha256",LocalUbuntuVueHelperPolicy.SOURCE_BINDING_SHA256);put("closureSha256",text(h,"closureSha256"));put("closurePath","${stage.absolutePath}/$CLOSURE_FILE");put("proofs",JsonArray(proofs.map{(path,hash)->buildJsonObject{put("path",path);put("sha256",hash)}}))}.toString()+"\n"
        return mapOf(FILE_NAME to a,CLOSURE_FILE to c,HEALTH_SEED to seed)
    }
    fun finalHealthSeed(seed:String,stage:String,finalGuest:String):String{require(finalGuest==LocalUbuntuVuePolicy.ROOT);val o=LocalUbuntuPowerShellRuntimePolicy.strictObject(seed,65536);fun relocated(value:String)=if(value==stage||value.startsWith("$stage/"))finalGuest+value.removePrefix(stage)else value
        val fields=setOf("packageRoot","npmRoot","serverExecutable","typescriptLspExecutable","typescriptServerExecutable","typescriptLibrary","pluginExecutable","closurePath")
        return JsonObject(o.mapValues{(key,value)->if(key in fields)JsonPrimitive(relocated(value.jsonPrimitive.content))else if(key=="proofs")JsonArray(value.jsonArray.map{v->JsonObject(v.jsonObject+("path" to JsonPrimitive(relocated(v.jsonObject.getValue("path").jsonPrimitive.content))))})else value}).toString()+"\n"}
    private fun generation(record:ManagedPackageRecord,appRoot:String,active:()->Unit):Pair<JsonObject,String>{requireRecord(record,appRoot);val root=File(record.installRoot);require(root.canonicalPath==root.absolutePath);val a=objectAt(File(root,FILE_NAME),65536,active);val seal=sha(File(root,"SHA256SUMS"),16777216,active)
        require(a["schema"]==JsonPrimitive(1)&&text(a,"policy")==POLICY&&text(a,"family")==record.familyId&&text(a,"version")==record.version&&text(a,"final")==packageRoot(record.familyId)&&text(a,"archiveSha256")==record.artifactSha256&&a["helpers"]==mapping(expectedHelperHashes));require(text(a,"sourceCommit")==LocalUbuntuVueHelperPolicy.SOURCE_COMMIT&&text(a,"sourceBindingSha256")==LocalUbuntuVueHelperPolicy.SOURCE_BINDING_SHA256)
        require(text(a,"activation")==record.metadata[LocalManagedPackageMetadata.ACTIVATION_ID_KEY]&&NimRuntimeClosure.readText(File(root,"DROIDE_ACTIVATION_ID"),128,active)==text(a,"activation")&&seal==record.metadata[LocalManagedPackageMetadata.SEAL_SHA256_KEY]);closure(root,a,active)
        return a to seal}
    private fun closure(root:File,a:JsonObject,active:()->Unit):Map<String,String>{val c=objectAt(File(root,CLOSURE_FILE),65536,active);require(c.keys==setOf("schema","files","sha256")&&c["schema"]==JsonPrimitive(1)&&text(c,"sha256")==text(a,"closureSha256"));val files=c.getValue("files").jsonObject;require(files.size in 1..67);val values=files.mapValues{(path,value)->NimRuntimeClosure.requireRelative(path);require(path.matches(Regex("(?:(?:usr/)?lib(?:64)?/.*|etc/ld\\.so\\.(?:cache|preload)|(?:usr/)?bin/(?:dash|sh))")));value.jsonPrimitive.content.also{require(it.matches(Regex("[0-9a-f]{64}")))}};require(NimRuntimeClosure.sha256(values.toSortedMap().entries.joinToString("\n"){"${it.key}\u0000${it.value}"})==text(c,"sha256"));return values}
    suspend fun inspect(appRoot:String,server:ManagedPackageRecord,records:List<ManagedPackageRecord>,selections:Map<String,String>,discovered:String):VueManagedLaunchIdentity?{val context=currentCoroutineContext();val active={context.ensureActive()};return try{
        require(records.size<=512&&records.map{it.familyId to it.version}.distinct().size==records.size);require(server.familyId==LocalUbuntuVuePolicy.FAMILY&&server.version==LocalUbuntuVuePolicy.VERSION);require(LocalLinuxPackageEnvironment.selectedRecords(records,selections,appRoot).singleOrNull{it.familyId==server.familyId}==server)
        val helper=records.single{it.familyId==LocalUbuntuVueHelperPolicy.FAMILY&&it.version==LocalUbuntuVueHelperPolicy.VERSION};require(selections[server.familyId]==null||selections[server.familyId]==server.version);require(selections[helper.familyId]==null||selections[helper.familyId]==helper.version);require(LocalLinuxPackageEnvironment.selectedRecords(records,selections,appRoot).singleOrNull{it.familyId==helper.familyId}==helper);val(a,seal)=generation(server,appRoot,active);val(h,hseal)=generation(helper,appRoot,active);require(server.dependencies==listOf(LocalUbuntuVueHelperPolicy.KEY)&&a["dependencyReceipts"]==mapping(mapOf(helper.familyId to receiptSha(helper)))&&h["dependencyReceipts"]==JsonObject(emptyMap()))
        val launch="${LocalUbuntuVuePolicy.ROOT}/payload/bin/vue-language-server";require(discovered in setOf(LocalUbuntuVuePolicy.COMMAND,launch,"/opt/droide/bin/vue-language-server"));val projection=if(discovered=="/opt/droide/bin/vue-language-server")NimRuntimeClosure.readText(File(appRoot,"managed/ubuntu-bin/vue-language-server"),65536,active).also{require(it=="#!/bin/sh\nexec '$launch' \"${'$'}@\"\n")}else"version-specific"
        val root=LocalUbuntuVuePolicy.ROOT;VueManagedLaunchIdentity(server.familyId,server.version,helper.familyId,helper.version,POLICY,receiptSha(server),receiptSha(helper),seal,hseal,NimRuntimeClosure.sha256(mapping(selections.filterKeys{LocalUbuntuVuePolicy.isFamily(it)}).toString()+":"+projection),discovered,launch,"$root/${LocalUbuntuVuePolicy.VUE_ENTRY}","$root/${LocalUbuntuVuePolicy.TSLSP_ENTRY}","$root/${LocalUbuntuVuePolicy.TS_ENTRY}","$root/${LocalUbuntuVuePolicy.TS_LIBRARY}","$root/${LocalUbuntuVuePolicy.PLUGIN_ENTRY}",LocalUbuntuVueHelperPolicy.EXECUTABLE,"$root/payload/npm",text(a,"activation"),text(h,"activation"),text(a,"configSha256"),LocalUbuntuVueHelperPolicy.SOURCE_BINDING_SHA256,text(a,"closureSha256")).also{require(LspVueLaunchPolicy.matchesIdentity(it))}
    }catch(c:CancellationException){throw c}catch(_:Exception){null}}
    suspend fun provePackage(appRoot:String,record:ManagedPackageRecord,active:()->Unit={}){
        val(a,_)=generation(record,appRoot,active);val root=File(record.installRoot);helpers(root,active);val verified=requireNotNull(LocalPackageIntegrity.verifiedChecksums(root,File(root,"SHA256SUMS"),exactInventory=true));require(verified.size<=16416)
        var count=0;Files.walk(root.toPath()).use{stream->stream.forEach{p->active();require(++count<=32832);val relative=root.toPath().relativize(p).toString().replace(File.separatorChar,'/');if(record.familyId==LocalUbuntuVuePolicy.FAMILY||!relative.startsWith("payload/tree/")){require(!Files.isSymbolicLink(p));require(Files.isDirectory(p,NOFOLLOW_LINKS)||Files.isRegularFile(p,NOFOLLOW_LINKS));if(Files.isRegularFile(p,NOFOLLOW_LINKS)){val stat=android.system.Os.lstat(p.toString());require(stat.st_nlink==1L&&stat.st_mode and 3072==0);val expected=if(relative.startsWith("payload/bin/")||relative.startsWith("payload/host-bin/"))493 else 420;require(stat.st_mode and 511==expected)}}}}
        if(record.familyId==LocalUbuntuVuePolicy.FAMILY){LocalUbuntuVuePolicy.requireReview(objectAt(File(root,"RECIPE_LOCK.json")));LocalUbuntuVuePolicy.validateInstalledLayout(root,active);val seed=objectAt(File(root,HEALTH_SEED));require(text(seed,"packageRoot")==LocalUbuntuVuePolicy.ROOT&&text(seed,"npmRoot")=="${LocalUbuntuVuePolicy.ROOT}/payload/npm"&&text(seed,"helperExecutable")==LocalUbuntuVueHelperPolicy.EXECUTABLE&&text(seed,"closureSha256")==text(a,"closureSha256"))}
        else{val inv=LocalUbuntuVueHelperPolicy.requireTree(File(root,"payload/tree/${LocalUbuntuVueHelperPolicy.ENTRY}"),active);require(sha(File(root,"TREE_SHA256SUMS"),16777216,active)==text(a,"treeManifestSha256"));val original=requireNotNull(LocalPackageIntegrity.verifiedChecksums(File(root,"payload/tree"),File(root,"TREE_SHA256SUMS"),exactInventory=true,manifestRoot=root));for((relative,hash)in inv.hashes){require(verified["payload/tree/$relative"]==hash&&original[relative]==hash)}
            val links=NimRuntimeClosure.readText(File(root,"TREE_LINKS.tsv"),524288,active).lineSequence().filter{it.isNotEmpty()}.associate{row->val parts=row.split('\t');require(parts.size==3);parts[0] to parts[1]};require(links==inv.links);require(LocalUbuntuVueHelperPolicy.requireConfiguration(File(root,"payload/tree/${LocalUbuntuVueHelperPolicy.CONFIG}"),active)==text(a,"configSha256"));val fresh=NimRuntimeClosure.requireExecutionClosure(listOf(inv),File(appRoot,"guest/${FoundryUbuntuGuestEnvironmentSpec.ROOT_DIR}/rootfs"),emptySet(),active);require(fresh.files==closure(root,a,active))}
        val guestRoot=File(appRoot,"guest/${FoundryUbuntuGuestEnvironmentSpec.ROOT_DIR}/rootfs");for((relative,hash)in closure(root,a,active)){val file=requireNotNull(NimRuntimeClosure.resolveGuestFile(guestRoot,"/$relative",active));require(sha(file,536870912,active)==hash)}
    }
    suspend fun proveOwnedPackages(appRoot:String,server:ManagedPackageRecord,owned:List<ManagedPackageRecord>,active:()->Unit={}){val end=System.nanoTime()+30_000_000_000L;val bounded={active();check(System.nanoTime()<=end){"Vue protected proof deadline"}};require(server.familyId==LocalUbuntuVuePolicy.FAMILY&&owned.size==1&&owned.single().familyId==LocalUbuntuVueHelperPolicy.FAMILY);val helper=owned.single();val a=generation(server,appRoot,bounded).first;val h=generation(helper,appRoot,bounded).first;require(a["dependencyReceipts"]==mapping(mapOf(helper.familyId to receiptSha(helper)))&&text(a,"closureSha256")==text(h,"closureSha256")&&text(a,"configSha256")==text(h,"configSha256"));provePackage(appRoot,helper,bounded);provePackage(appRoot,server,bounded)}
    suspend fun prove(appRoot:String,identity:VueManagedLaunchIdentity,records:List<ManagedPackageRecord>,active:()->Unit){require(LspVueLaunchPolicy.matchesIdentity(identity));val server=records.single{it.familyId==identity.familyId&&it.version==identity.version};val helper=records.single{it.familyId==identity.helperFamilyId&&it.version==identity.helperVersion};require(receiptSha(server)==identity.receiptSha256&&receiptSha(helper)==identity.helperReceiptSha256);val(a,s)=generation(server,appRoot,active);val(h,hs)=generation(helper,appRoot,active);require(s==identity.sealSha256&&hs==identity.helperSealSha256&&text(a,"activation")==identity.activationIdentity&&text(h,"activation")==identity.helperActivationIdentity&&text(a,"configSha256")==identity.helperConfigSha256&&text(a,"closureSha256")==identity.closureSha256);proveOwnedPackages(appRoot,server,listOf(helper),active)}
    fun guestWrapper(family:String,guestRoot:String):String {
        require(LocalUbuntuVuePolicy.isFamily(family)&&guestRoot==packageRoot(family))
        val helperOnly=family==LocalUbuntuVueHelperPolicy.FAMILY
        val command=LocalUbuntuVueLspHealth.installCommand(guestRoot,LocalUbuntuVueHelperPolicy.EXECUTABLE,helperOnly)
        fun q(value:String)="'"+value.replace("'","'\\''")+"'"
        return "#!/bin/sh\nset -eu\nif [ \"${'$'}{1-}\" = --health ] && [ \"${'$'}#\" -eq 1 ]; then exec "+command.joinToString(" ",transform=::q)+"; fi\nprintf '%s\\n' 'Vue requires its typed paired owner; direct launch is unavailable.' >&2\nexit 64\n"
    }
    fun stageHealthCommand(stage:File,helper:ManagedPackageRecord):List<String>{require(helper.familyId==LocalUbuntuVueHelperPolicy.FAMILY);return LocalUbuntuVueLspHealth.installCommand(stage.absolutePath,LocalUbuntuVueHelperPolicy.EXECUTABLE,false)}
    fun helperHealthCommand(stage:File):List<String> = LocalUbuntuVueLspHealth.installCommand(stage.absolutePath,"${stage.absolutePath}/payload/tree/${LocalUbuntuVueHelperPolicy.ENTRY}",true)
}
